export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // tenant -> key -> original receipt. Nested Maps keep tenant and key separate.
  readonly #receipts = new Map<string, Map<string, Receipt>>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    let byKey = this.#receipts.get(tenant);
    if (byKey === undefined) {
      byKey = new Map<string, Receipt>();
      this.#receipts.set(tenant, byKey);
    }
    const original = byKey.get(key);
    if (original !== undefined) {
      if (original.cents !== cents) throw new Error('key conflict');
      return original;
    }
    // No await before recording: a concurrent call sees this entry as soon as it is written.
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    byKey.set(key, receipt);
    return receipt;
  }
}
