cd /workspace && cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');

const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

const isInvalidPayment = err => err instanceof Error && err.message === 'invalid payment';
const isKeyConflict = err => err instanceof Error && err.message === 'key conflict';
const tick = () => new Promise(resolve => setTimeout(resolve, 5));

// Records every acknowledged receipt; the first failures.length calls throw those errors.
function scriptedTransport(failures = []) {
  const calls = [];
  const queue = [...failures];
  return {
    calls,
    async acknowledge(receipt) {
      calls.push(receipt);
      if (queue.length > 0) throw queue.shift();
    },
  };
}

// Counts ledger debits attempted through apply, including ones rejected by the ledger.
class CountingLedger extends Ledger {
  applyCalls = 0;
  async apply(tenant, key, cents) {
    this.applyCalls++;
    return super.apply(tenant, key, cents);
  }
}

async function originalChecks() {
  const ledger = new Ledger(); const receipts = [];
  const service = new PaymentService(ledger, { acknowledge: async r => { receipts.push(r); } });
  assert.deepEqual(await service.pay('shop', 'sale', 123), { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
  assert.equal(ledger.entries.length, 1); assert.equal(receipts.length, 1);
  await assert.rejects(service.pay('shop', 'bad', 0), /invalid payment/);
}

async function transientAfterCommitRetriesWithoutDebit() {
  const ledger = new Ledger();
  const transport = scriptedTransport([new Transient('ack lost'), new Transient('ack lost')]);
  const service = new PaymentService(ledger, transport);
  const receipt = await service.pay('shop', 'order-1', 500, 3);
  assert.deepEqual(receipt, { id: 1, tenant: 'shop', key: 'order-1', cents: 500 });
  assert.equal(ledger.entries.length, 1, 'retries must not add debits');
  assert.equal(transport.calls.length, 3);
  for (const forwarded of transport.calls) assert.strictEqual(forwarded, receipt);
}

async function exhaustedRetriesRethrowFinalError() {
  const ledger = new Ledger();
  const last = new Transient('final');
  const transport = scriptedTransport([new Transient('first'), new Transient('second'), last]);
  const service = new PaymentService(ledger, transport);
  await assert.rejects(service.pay('shop', 'order-2', 500, 3), err => err === last);
  assert.equal(transport.calls.length, 3);
  assert.equal(ledger.entries.length, 1);
}

async function defaultAttemptsIsThree() {
  const ledger = new Ledger();
  const failures = [new Transient('t1'), new Transient('t2'), new Transient('t3'), new Transient('t4')];
  const transport = scriptedTransport(failures);
  const service = new PaymentService(ledger, transport);
  await assert.rejects(service.pay('shop', 'order-3', 500), err => err === failures[2]);
  assert.equal(transport.calls.length, 3);
  assert.equal(ledger.entries.length, 1);
}

async function attemptsBoundsAreRespected() {
  const one = scriptedTransport([new Transient('once')]);
  await assert.rejects(new PaymentService(new Ledger(), one).pay('shop', 'a1', 1, 1), /once/);
  assert.equal(one.calls.length, 1, 'attempts=1 means a single try');

  const five = scriptedTransport([new Transient('1'), new Transient('2'), new Transient('3'), new Transient('4')]);
  const ledger = new Ledger();
  const receipt = await new PaymentService(ledger, five).pay('shop', 'a5', 1, 5);
  assert.equal(five.calls.length, 5);
  assert.equal(ledger.entries.length, 1);
  assert.strictEqual(five.calls[4], receipt);
}

async function nonTransientErrorsAreNotRetried() {
  const boom = new Error('boom');
  const transport = scriptedTransport([boom]);
  const ledger = new Ledger();
  await assert.rejects(new PaymentService(ledger, transport).pay('shop', 'x1', 10, 5), err => err === boom);
  assert.equal(transport.calls.length, 1);
  assert.equal(ledger.entries.length, 1);

  const dbError = new Error('db down');
  class FailingLedger extends CountingLedger {
    async apply() { this.applyCalls++; throw dbError; }
  }
  const failing = new FailingLedger();
  const quiet = scriptedTransport();
  await assert.rejects(new PaymentService(failing, quiet).pay('shop', 'x2', 10, 5), err => err === dbError);
  assert.equal(failing.applyCalls, 1);
  assert.equal(quiet.calls.length, 0, 'transport is not touched when the ledger fails');
}

async function concurrentEqualCallsDebitOnce() {
  const ledger = new Ledger();
  const transport = { calls: [], async acknowledge(receipt) { this.calls.push(receipt); await tick(); } };
  const service = new PaymentService(ledger, transport);
  const results = await Promise.all([1, 2, 3, 4, 5].map(() => service.pay('shop', 'sale-c', 700)));
  assert.equal(ledger.entries.length, 1);
  for (const r of results) assert.strictEqual(r, results[0]);
  assert.deepEqual(results[0], { id: 1, tenant: 'shop', key: 'sale-c', cents: 700 });
  for (const forwarded of transport.calls) assert.strictEqual(forwarded, results[0]);
}

async function concurrentCallsWithTransientAckDebitOnce() {
  const ledger = new Ledger();
  let first = true;
  const transport = {
    calls: [],
    async acknowledge(receipt) {
      this.calls.push(receipt);
      await tick();
      if (first) { first = false; throw new Transient('lost'); }
    },
  };
  const service = new PaymentService(ledger, transport);
  const results = await Promise.all([1, 2, 3].map(() => service.pay('shop', 'sale-t', 42)));
  assert.equal(ledger.entries.length, 1);
  for (const r of results) assert.strictEqual(r, results[0]);
}

async function reusedKeyWithDifferentAmountConflicts() {
  const ledger = new Ledger();
  const transport = scriptedTransport();
  const service = new PaymentService(ledger, transport);
  await service.pay('shop', 'k', 100);
  await assert.rejects(service.pay('shop', 'k', 200), isKeyConflict);
  assert.equal(ledger.entries.length, 1);
  assert.equal(transport.calls.length, 1, 'conflict is not acknowledged');
  await assert.rejects(ledger.apply('shop', 'k', 999), isKeyConflict);
  assert.equal(ledger.entries.length, 1);
}

async function concurrentConflictingAmountsDebitOnce() {
  const ledger = new Ledger();
  const service = new PaymentService(ledger, scriptedTransport());
  const outcomes = await Promise.allSettled([service.pay('shop', 'race', 100), service.pay('shop', 'race', 200)]);
  assert.equal(outcomes.filter(o => o.status === 'fulfilled').length, 1);
  const rejected = outcomes.filter(o => o.status === 'rejected');
  assert.equal(rejected.length, 1);
  assert.ok(isKeyConflict(rejected[0].reason));
  assert.equal(ledger.entries.length, 1);
}

async function idempotencyIsScopedByTenantAndKey() {
  const ledger = new Ledger();
  const service = new PaymentService(ledger, scriptedTransport());
  await service.pay('a', 'k', 100);
  await service.pay('b', 'k', 200);
  await service.pay('a', 'j', 300);
  await service.pay('x|y', 'z', 1);
  await service.pay('x', 'y|z', 2);
  await service.pay('__proto__', 'k', 5);
  assert.equal(ledger.entries.length, 6);
}

async function invalidInputTouchesNothing() {
  const invalidPayments = [
    ['', 'k', 1], ['shop', '', 1], [undefined, 'k', 1], ['shop', undefined, 1], [null, 'k', 1], [5, 'k', 1],
    ['shop', 'k', 0], ['shop', 'k', -1], ['shop', 'k', 1.5], ['shop', 'k', NaN], ['shop', 'k', Infinity], ['shop', 'k', '5'],
    ['shop', 'k', 1, 0], ['shop', 'k', 1, 6], ['shop', 'k', 1, 1.5], ['shop', 'k', 1, '2'],
    ['shop', 'k', 1, NaN], ['shop', 'k', 1, null], ['shop', 'k', 1, -1],
  ];
  for (const args of invalidPayments) {
    const ledger = new CountingLedger();
    const transport = scriptedTransport();
    const service = new PaymentService(ledger, transport);
    await assert.rejects(service.pay(...args), isInvalidPayment, JSON.stringify(args));
    assert.equal(ledger.applyCalls, 0, `ledger touched for ${JSON.stringify(args)}`);
    assert.equal(transport.calls.length, 0, `transport touched for ${JSON.stringify(args)}`);
  }
}

async function main() {
  await originalChecks();
  await transientAfterCommitRetriesWithoutDebit();
  await exhaustedRetriesRethrowFinalError();
  await defaultAttemptsIsThree();
  await attemptsBoundsAreRespected();
  await nonTransientErrorsAreNotRetried();
  await concurrentEqualCallsDebitOnce();
  await concurrentCallsWithTransientAckDebitOnce();
  await reusedKeyWithDifferentAmountConflicts();
  await concurrentConflictingAmountsDebitOnce();
  await idempotencyIsScopedByTenantAndKey();
  await invalidInputTouchesNothing();
}
module.exports = main();
EOF
